/bin/bash -lc "cd /workspace && python - <<'PY'
import openpyxl, glob, collections, os
files=glob.glob('inputs/CHIP_DP10_GQ20_PASS/*.xlsx')
zyg=collections.Counter(); genes=collections.defaultdict(collections.Counter)
# target 556-PF
for f in files:
    base=os.path.basename(f)
    try:
        wb=openpyxl.load_workbook(f, read_only=False, data_only=True)
        ws=wb.active
        header=None
        for r in ws.iter_rows(values_only=True):
            if header is None:
                header=r
                idx={str(h):i for i,h in enumerate(header)}
                z=idx.get('Zygosity'); g=idx.get('Gene Names')
                continue
            zv=r[z] if z is not None else None
            zyg[zv]+=1
            gv=r[g] if g is not None else None
            if base=='230209_Exome_GRCh38_CHIP_556-PF.xlsx':
                genes[gv][zv]+=1
    except Exception as e:
        print('ERR',base,e)
print('unique zyg all files', zyg)
print('556 gene counts by zyg:')
for g,c in genes.items():
    print(g, dict(c), 'nonref', sum(v for k,v in c.items() if k"'!='"'Reference'))
print('total nonref genes')
for g,c in genes.items():
    s=sum(v for k,v in c.items() if k"'!='"'Reference')
    if s: print(g,s)
PY"
